import React, { useState, useEffect } from 'react';
import { FiPlus } from 'react-icons/fi';
import { isValidText, isValidPositiveNumber } from '../utils/helpers';
import eventService from '../services/eventService';
import '../styles/Pages.css';

const StallForm = ({ initialData, onSubmit, loading }) => {
  const [formData, setFormData] = useState(initialData || {
    stallName: '',
    event: '',
    location: '',
    category: 'food',
    size: 'medium',
    price: 0,
    description: '',
  });
  const [errors, setErrors] = useState({});
  const [events, setEvents] = useState([]);
  const [loadingEvents, setLoadingEvents] = useState(false);

  // Fetch events for dropdown
  useEffect(() => {
    fetchEvents();
  }, []);

  const fetchEvents = async () => {
    setLoadingEvents(true);
    try {
      const data = await eventService.getApprovedEvents();
      setEvents(data);
    } catch (error) {
      console.error('Error fetching events:', error);
    } finally {
      setLoadingEvents(false);
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: name === 'price' ? parseFloat(value) || 0 : value,
    }));
    // Clear field error when user starts typing
    if (errors[name]) {
      setErrors(prev => ({
        ...prev,
        [name]: '',
      }));
    }
  };

  const validateForm = () => {
    const newErrors = {};

    // Stall name validation
    if (!formData.stallName.trim()) {
      newErrors.stallName = 'Stall name is required';
    } else if (!isValidText(formData.stallName, 3)) {
      newErrors.stallName = 'Stall name must be at least 3 characters';
    }

    // Event validation
    if (!formData.event) {
      newErrors.event = 'Event selection is required';
    }

    // Location validation
    if (!formData.location.trim()) {
      newErrors.location = 'Location is required';
    } else if (!isValidText(formData.location, 3)) {
      newErrors.location = 'Location must be at least 3 characters';
    }

    // Price validation
    if (!formData.price) {
      newErrors.price = 'Price is required';
    } else if (!isValidPositiveNumber(formData.price)) {
      newErrors.price = 'Price must be a positive number';
    }

    // Description validation (optional)
    if (formData.description && !isValidText(formData.description, 10)) {
      newErrors.description = 'Description must be at least 10 characters if provided';
    }

    return newErrors;
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    // Validate form
    const newErrors = validateForm();
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    onSubmit(formData);
  };

  return (
    <form className="event-form stall-form" onSubmit={handleSubmit}>
      <div className="form-group">
        <label htmlFor="stallName">Stall Name *</label>
        <input
          type="text"
          id="stallName"
          name="stallName"
          value={formData.stallName}
          onChange={handleChange}
          required
          placeholder="Enter stall name (minimum 3 characters)"
          className={errors.stallName ? 'input-error' : ''}
        />
        {errors.stallName && <span className="error-text">{errors.stallName}</span>}
      </div>

      <div className="form-group">
        <label htmlFor="event">Select Event *</label>
        <select
          id="event"
          name="event"
          value={formData.event}
          onChange={handleChange}
          required
          className={errors.event ? 'input-error' : ''}
          disabled={loadingEvents}
        >
          <option value="">-- Select an Event --</option>
          {events.map(event => (
            <option key={event._id} value={event._id}>
              {event.title} ({new Date(event.startDate).toLocaleDateString()})
            </option>
          ))}
        </select>
        {errors.event && <span className="error-text">{errors.event}</span>}
      </div>

      <div className="form-row">
        <div className="form-group">
          <label htmlFor="location">Location/Booth Number *</label>
          <input
            type="text"
            id="location"
            name="location"
            value={formData.location}
            onChange={handleChange}
            required
            placeholder="e.g., Hall A, Section B"
            className={errors.location ? 'input-error' : ''}
          />
          {errors.location && <span className="error-text">{errors.location}</span>}
        </div>

        <div className="form-group">
          <label htmlFor="size">Stall Size *</label>
          <select
            id="size"
            name="size"
            value={formData.size}
            onChange={handleChange}
            required
          >
            <option value="small">Small (1x1 meter)</option>
            <option value="medium">Medium (2x2 meters)</option>
            <option value="large">Large (3x3 meters)</option>
          </select>
        </div>
      </div>

      <div className="form-row">
        <div className="form-group">
          <label htmlFor="category">Category *</label>
          <select
            id="category"
            name="category"
            value={formData.category}
            onChange={handleChange}
            required
          >
            <option value="food">Food & Beverages</option>
            <option value="crafts">Crafts & Art</option>
            <option value="retail">Retail & Products</option>
            <option value="other">Other</option>
          </select>
        </div>

        <div className="form-group">
          <label htmlFor="price">Price (LKR) *</label>
          <input
            type="number"
            id="price"
            name="price"
            value={formData.price}
            onChange={handleChange}
            required
            placeholder="Enter price"
            min="0"
            step="100"
            className={errors.price ? 'input-error' : ''}
          />
          {errors.price && <span className="error-text">{errors.price}</span>}
        </div>
      </div>

      <div className="form-group">
        <label htmlFor="description">Additional Details</label>
        <textarea
          id="description"
          name="description"
          value={formData.description}
          onChange={handleChange}
          placeholder="Describe your stall offerings, business details, etc. (minimum 10 characters if provided)"
          rows={4}
          className={errors.description ? 'input-error' : ''}
        />
        {errors.description && <span className="error-text">{errors.description}</span>}
      </div>

      <div className="form-group info-message">
        <p>📋 Your stall request will be pending admin approval before being visible to event organizers.</p>
      </div>

      <button 
        type="submit" 
        className="btn-primary"
        disabled={loading || loadingEvents}
      >
        {loading ? 'Submitting...' : (<><FiPlus /> Request Stall</>)}
      </button>
    </form>
  );
};

export default StallForm;
